insert into public.home_content_blocks (content_key, payload, updated_at) values
  ('currentFocusDescription', '"Greetings, Rivals! We''re thrilled to announce the upcoming patch drops on October 29th, 2026, at 09:00:00 (UTC)! It includes new store bundles and cosmetics, plus hero fixes."'::jsonb, '2026-10-30T03:00:16.327Z'::timestamptz),
  ('currentFocusTitle', '"Marvel Rivals Version 20261029 Patch Notes"'::jsonb, '2026-10-30T03:00:16.327Z'::timestamptz),
  ('featuredGuides', '[{"title":"Strategic Cover Usage","description":"Minimize your hitbox, isolate one angle, scout before peeking, and return to safety after each shot.","path":"/strategic-cover","tag":"Guide Notes"},{"title":"Power Positions","description":"Use map locations that create options, passive pressure, information, and safer objective control.","path":"/power-positions","tag":"Guide Notes"},{"title":"Starter Fundamentals Path","description":"A five-lesson route through cover, high ground, rotations, timing, and target priority.","path":"/learning-paths","tag":"Learning Path"}]'::jsonb, '2026-06-19 07:58:13+00'::timestamptz),
