  ('latestTuning', '{"category":"Balance Update","date":"October 6, 2026","title":"Marvel Rivals Version 20261009 Balance Post","description":"ADJUSTMENTS A new wave of adjustments is on the way! Iron Man is locking onto targets with a brand-new missile mechanic, Phoenix is sparking up her damage, Gorr is slightly tweaking the lethality of his scythe, and Jubilee is bringing even more explosive healing to the fray.","sourceUrl":"https://www.marvelrivals.com/balancepost/20261006/41667_1315864.html"}'::jsonb, '2026-10-30T03:00:16.327Z'::timestamptz),
