  ('seasonEvents', '[{"label":"Limited-time event","title":"Night of Illusions","description":"A mysterious man, fixated on an unknown witch, mistook the number \"4\" on her person for her actual name. Driven by this obsession, he attempts to sacrifice four \"monsters\" to complete a summoning ritual. A small animal, an ancient beast,…"}]'::jsonb, '2026-10-30T03:00:16.327Z'::timestamptz),
