ttps://r.res.easebar.com/pic/20261020/e4b912b0-825b-4e4a-af64-e26bfc939fac.png","thumbnailAlt":"Join Twitch Path to Doomsday Event & Go for 3,000 Gifted Subs! thumbnail","publishedAt":"2026/10/20"},{"label":"Official News","title":"Art Vision Vol. 06 // Behind The Scenes (Part 1): Dedication and Passion","description":"It''s time to check in with the Marvel Rivals art team: Art Vision Vol. 06 is here!","sourceUrl":"https://www.marvelrivals.com/20261019/41525_1316982.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261019/dbb21b4c-1fcb-4cdd-873b-7d6289b4ad5a.jpg","thumbnailAlt":"Art Vision Vol. 06 // Behind The Scenes (Part 1): Dedication and Passion thumbnail","publishedAt":"2026/10/19"},{"label":"Official News","title":"Speech Moderation and Penalties","description":"Greetings, Rivals! A positive communication environment is a vital component of any team-based competitive experience.","sourceUrl":"https://www.marvelrivals.com/announcements/20261016/40955_1316802.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261016/fe12c032-83ad-4e3a-a6d6-3cda3199ef94.jpg","thumbnailAlt":"Speech Moderation and Penalties thumbnail","publishedAt":"2026/10/16"},{"label":"Official News","title":"Use of Mods and Violation Management","description":"Greetings, Rivals! During our recent investigations into account violations, we discovered that certain Mods utilized by players involve memory injection and modification behaviors.","sourceUrl":"https://www.marvelrivals.com/announcements/20261015/40955_1316797.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261016/3dae3f83-e521-469e-a405-ba9ee5e72c72.jpg","thumbnailAlt":"Use of Mods and Violation Management thumbnail","publishedAt":"2026/10/15"},{"label":"Patch Notes","title":"Marvel Rivals Version 20261015 Patch Notes","description":"Greetings, Rivals! We''re thrilled to announce the upcoming patch drops on October 15th, 2026, at 09:00:00 (UTC)!","sourceUrl":"https://www.marvelrivals.com/gameupdate/20261014/41548_1316588.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261014/a1d468a0-73d2-4f21-8de4-d28bd5481b4c.png","thumbnailAlt":"Marvel Rivals Version 20261015 Patch Notes thumbnail","publishedAt":"2026/10/14"},{"label":"Season Update","title":"Season 10.5: New Modes and Halloween // Dev Vision Vol. 22 | Marvel Rivals","description":"The spookiest season yet is almost here! Tune in to Dev Vision Vol.","sourceUrl":"https://www.marvelrivals.com/devdiaries/20261007/40954_1315872.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261007/960cf2c7-f460-4cb5-bbb3-f8007767c298.jpg","thumbnailAlt":"Season 10.5: New Modes and Halloween // Dev Vision Vol. 22 | Marvel Rivals thumbnail","publishedAt":"2026/10/07"},{"label":"Patch Notes","title":"Marvel Rivals Version 20261009 Patch Notes - Season 10.5 Arrives","description":"Greetings, Rivals! This season, we are unveiling all-new Marvel Cinematic Universe inspired game modes!","sourceUrl":"https://www.marvelrivals.com/gameupdate/20261006/41548_1315865.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261006/8a79ba12-0c93-4477-8490-062e4ee491eb.png","thumbnailAlt":"Marvel Rivals Version 20261009 Patch Notes - Season 10.5 Arrives thumbnail","publishedAt":"2026/10/06"},{"label":"Balance Update","title":"Marvel Rivals Version 20261009 Balance Post","description":"ADJUSTMENTS A new wave of adjustments is on the way! Iron Man is locking onto targets with a brand-new missile mechanic, Phoenix is sparking up her damage, Gorr is slightly tweaking the lethality of his scythe, and Jubilee is bringing even more explosive healing to the fray.","sourceUrl":"https://www.marvelrivals.com/balancepost/20261006/41667_1315864.html","thumbnailUrl":"https://r.res.easebar.com/pic/20261006/53852dbc-73a1-4eb5-8dc3-8f7debda771e.png","thumbnailAlt":"Marvel Rivals Version 20261009 Balance Post thumbnail","publishedAt":"2026/10/06"},{"label":"Patch Notes","title":"Marvel Rivals Version 20261001 Patch Notes","description":"Greetings, Rivals! We''re thrilled to announce the upcoming patch drops on October 1st, 2026, at 09:00:00 (UTC)!","sourceUrl":"https://www.marvelrivals.com/gameupdate/20260930/41548_1315568.html","thumbnailUrl":"https://r.res.easebar.com/pic/20260930/efacbc57-d06c-4ffa-ae3f-822ce403dd64.png","thumbnailAlt":"Marvel Rivals Version 20261001 Patch Notes thumbnail","publishedAt":"2026/09/30"},{"label":"Patch Notes","title":"Marvel Rivals Version 20260924 Patch Notes","description":"Greetings, Rivals! We''re thrilled to announce the upcoming patch drops on September 24th, 2026, at 09:00:00 (UTC)!","sourceUrl":"https://www.marvelrivals.com/gameupdate/20260923/41548_1314808.html","thumbnailUrl":"https://r.res.easebar.com/pic/20260923/1043a8ec-cc13-4246-b55d-7cef1c8e8708.png","thumbnailAlt":"Marvel Rivals Version 20260924 Patch Notes thumbnail","publishedAt":"2026/09/23"}],"battlePass":{"currentSeason":"Season 10","battlePass":"New Modes and Halloween","seasonStory":"New Modes and Halloween","latestHero":"Gorr The God Butcher","latestHeroImageUrl":"https://r.res.easebar.com/pic/20260911/c4f7de6b-1348-42e7-b27c-9c44afbf4f7f.png"}}'::jsonb, '2026-10-30T03:00:16.327Z'::timestamptz, 'success', null)
